object biblioteca {
  const juegos = [timbaElLeon, carlosDuty]
  var puntos = 0

  method juegos() {
    return juegos
  }

  method adquirirJuego(unJuego) {
    juegos.add(unJuego)
    puntos += 150
  }

  method borrarJuego(unJuego) {
    juegos.remove(unJuego)
  }

  method esDeGamer() {
    return self.puntos() > 1000 and juegos.size() > 5
  }

  method esJuegoRecomendable(unJuego) {
    return not juegos.contains(unJuego) and unJuego.esViolento()
  }

  method puntos() {
    return puntos
  }
}

